import{_ as t,o,c as s,ag as a}from"./chunks/framework.DFmy_ALI.js";const u=JSON.parse('{"title":"OAuth and MCP Kill Switches","description":"","frontmatter":{},"headers":[],"relativePath":"guide/oauth-mcp-kill-switches.md","filePath":"guide/oauth-mcp-kill-switches.md"}'),d={name:"guide/oauth-mcp-kill-switches.md"};function r(n,e,i,c,l,h){return o(),s("div",null,[...e[0]||(e[0]=[a('<h1 id="oauth-and-mcp-kill-switches" tabindex="-1">OAuth and MCP Kill Switches <a class="header-anchor" href="#oauth-and-mcp-kill-switches" aria-label="Permalink to &quot;OAuth and MCP Kill Switches&quot;">​</a></h1><p>OpenWave OAuth and Remote MCP are controlled by OpenWave Identity. Operators can turn access off globally, per environment, per owner type, per client, or per user grant.</p><h2 id="operator-surfaces" tabindex="-1">Operator surfaces <a class="header-anchor" href="#operator-surfaces" aria-label="Permalink to &quot;Operator surfaces&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Surface</th><th>Purpose</th></tr></thead><tbody><tr><td>OpenWave Identity <code>/portal/oauth</code></td><td>Control plane for clients, resource-server clients, scopes, environment gates, owner gates, delegated grants, secret rotation, token revocation, grant revocation, and kill switches.</td></tr><tr><td>OpenWave Identity <code>/portal/oauth-consent</code></td><td>Delegated authorization-code + PKCE consent review surface for the customer, bank, or operator role allowed by the requested scopes.</td></tr><tr><td>Astro <code>/astro_admin/oauth</code></td><td>Read-only readiness desk for protected-resource metadata, advertised scopes, resource-server credential posture, deployment flags, Identity metadata reachability, and tokenless <code>/mcp</code> protection smoke.</td></tr></tbody></table><p>Astro does not own OAuth policy. Do not paste client secrets, bearer tokens, merchant keys, bank keys, admin keys, OTPs, raw national IDs, or full account data into the Astro readiness desk or docs.</p><h2 id="astro-resource-server-configuration" tabindex="-1">Astro resource-server configuration <a class="header-anchor" href="#astro-resource-server-configuration" aria-label="Permalink to &quot;Astro resource-server configuration&quot;">​</a></h2><p>When <code>OPENWAVE_OAUTH_ENABLED=true</code>, Astro must authenticate to Identity&#39;s introspection endpoint as an approved resource-server OAuth client. Missing resource-server credentials fail closed.</p><table tabindex="0"><thead><tr><th>Env var</th><th>Purpose</th></tr></thead><tbody><tr><td><code>OPENWAVE_IDENTITY_OAUTH_URL</code></td><td>Identity OAuth issuer/API base, usually the Identity <code>/v1</code> base URL.</td></tr><tr><td><code>OPENWAVE_OAUTH_AUDIENCE</code></td><td>Audience Astro expects during introspection; default <code>astro</code>.</td></tr><tr><td><code>OPENWAVE_OAUTH_INTROSPECTION_CLIENT_ID</code></td><td>Identity OAuth client id with type <code>RESOURCE_SERVER</code>.</td></tr><tr><td><code>OPENWAVE_OAUTH_INTROSPECTION_CLIENT_SECRET</code></td><td>One-time secret stored only in the approved secret manager.</td></tr><tr><td><code>OPENWAVE_OAUTH_TIMEOUT_MS</code></td><td>Short fail-closed timeout for Identity metadata/introspection calls.</td></tr><tr><td><code>OPENWAVE_OAUTH_BEARER_RATE_LIMIT_PER_MINUTE</code></td><td>Per-source-IP OAuth bearer attempts Astro accepts before local <code>429</code> protection; default <code>120</code>.</td></tr><tr><td><code>OPENWAVE_OAUTH_BEARER_RATE_LIMIT_MAX_ENTRIES</code></td><td>Bounded counter capacity for OAuth bearer source-IP rate limits; default <code>20000</code>.</td></tr><tr><td><code>OPENWAVE_REMOTE_MCP_ENABLED</code></td><td>Enables <code>/mcp</code> only after OAuth validation is available.</td></tr></tbody></table><p>The resource-server client should have <code>openwave:tokens.introspect</code> and only the owner/environment posture needed by the deployment. Do not store its secret in markdown, tickets, logs, or screenshots.</p><p>Astro applies the bearer rate limit before token-shape checks and before Identity introspection. This keeps exact-shaped random bearer-token rotation local to Astro instead of allowing one source to create unbounded Identity introspection traffic.</p><p>Current production posture, activated on 2026-07-04:</p><ul><li>Identity resource-server client: <code>owrs_astro_prod</code></li><li>Neptune-owner MCP client: the approved owner-scoped client ID held in secret storage</li><li>Enabled: <code>oauth.global</code>, <code>mcp.global</code>, <code>environment.sandbox</code>, <code>owner.NEPTUNE</code></li><li>Disabled: <code>mcp.mutations</code>, <code>environment.live</code>, <code>owner.MERCHANT</code>, <code>owner.BANK</code>, <code>owner.CUSTOMER</code></li></ul><p>This means production Astro accepts Identity-issued Neptune-owner sandbox tokens for read-only Remote MCP. Live OAuth, merchant/bank/customer OAuth, and MCP write tools remain gated off.</p><h2 id="global-switches" tabindex="-1">Global switches <a class="header-anchor" href="#global-switches" aria-label="Permalink to &quot;Global switches&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Switch</th><th>Default</th><th>Effect</th></tr></thead><tbody><tr><td><code>oauth.global</code></td><td>off</td><td>Blocks token issuance and token introspection.</td></tr><tr><td><code>mcp.global</code></td><td>off</td><td>Blocks Remote MCP tool execution.</td></tr><tr><td><code>mcp.mutations</code></td><td>off</td><td>Blocks Remote MCP write tools even when a token has write scope.</td></tr><tr><td><code>environment.sandbox</code></td><td>on</td><td>Allows sandbox OAuth access.</td></tr><tr><td><code>environment.live</code></td><td>off</td><td>Allows live OAuth access.</td></tr><tr><td><code>owner.NEPTUNE</code></td><td>on</td><td>Allows Neptune owner clients.</td></tr><tr><td><code>owner.MERCHANT</code></td><td>off</td><td>Allows merchant clients.</td></tr><tr><td><code>owner.BANK</code></td><td>off</td><td>Allows bank clients.</td></tr><tr><td><code>owner.CUSTOMER</code></td><td>off</td><td>Allows customer delegated clients.</td></tr></tbody></table><h2 id="emergency-actions" tabindex="-1">Emergency actions <a class="header-anchor" href="#emergency-actions" aria-label="Permalink to &quot;Emergency actions&quot;">​</a></h2><p>Use the narrowest control that contains the issue:</p><ol><li>Disable a single client when one integration is compromised.</li><li>Revoke a user’s grants when delegated access is wrong.</li><li>Disable live access when production access must pause but sandbox can continue.</li><li>Disable <code>mcp.global</code> when agent access must stop immediately.</li><li>Disable <code>oauth.global</code> only when all OAuth access must stop.</li></ol><p>Existing raw merchant keys and portal sessions continue to work unless their separate controls are changed.</p><h2 id="astro-readiness-checks" tabindex="-1">Astro readiness checks <a class="header-anchor" href="#astro-readiness-checks" aria-label="Permalink to &quot;Astro readiness checks&quot;">​</a></h2><p>Before enabling production Remote MCP access, verify:</p><ol><li><code>GET https://astro.neptune.ly/.well-known/oauth-protected-resource</code> returns JSON, not the static UI.</li><li><code>authorization_servers</code> includes OpenWave Identity.</li><li><code>scopes_supported</code> includes <code>openwave:mcp.read</code> and <code>openwave:owner.ops.read</code>.</li><li><code>GET /api/v1/astro/admin/oauth/readiness</code> shows Identity metadata reachability and complete resource-server credential posture when OAuth is enabled.</li><li>A tokenless <code>POST https://astro.neptune.ly/mcp</code> returns a controlled protection response.</li><li>The Astro admin <code>/astro_admin/oauth</code> desk shows the same readiness posture.</li></ol><p>The <code>/mcp</code> smoke must not send credentials. HTTP <code>401</code> or <code>403</code> is acceptable. HTTP <code>200</code> with a JSON-RPC <code>error</code> envelope is also acceptable. A tokenless tools result is not acceptable.</p><p>For repeatable production checks from the Astro repo:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">scripts/openwave-prod-smoke.sh</span></span></code></pre></div><p>The script checks public health, Identity OAuth discovery, Astro protected-resource metadata, the Identity/Astro OAuth admin routes, and tokenless <code>/mcp</code> protection. It does not print or require secrets.</p><p>To include the admin readiness API, supply an Astro admin key only through the shell environment:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ASTRO_ADMIN_KEY</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$ASTRO_ADMIN_KEY</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> scripts/openwave-prod-smoke.sh</span></span></code></pre></div><p>The script passes the key as <code>X-OpenWave-Admin-Key</code> and does not echo it.</p><p>After an Identity-issued Neptune-owner token exists and Remote MCP is intentionally enabled, prove authenticated read-only MCP access with:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">OPENWAVE_MCP_TOKEN</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$OPENWAVE_MCP_TOKEN</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> scripts/openwave-mcp-auth-smoke.sh</span></span></code></pre></div><p>The token must include <code>openwave:mcp.read</code> and <code>openwave:owner.ops.read</code>. The script verifies <code>initialize</code>, <code>tools/list</code>, and <code>tools/call</code> for <code>astro_oauth_readiness</code> without printing token material.</p><p>For production evidence, record only pass/fail counts, client ids, switch posture, and route/status results. Do not copy bearer tokens, client secrets, API keys, OTPs, raw national IDs, raw phone lists, private keys, or full account data into the evidence note.</p><h2 id="audit" tabindex="-1">Audit <a class="header-anchor" href="#audit" aria-label="Permalink to &quot;Audit&quot;">​</a></h2><p>Every switch change, client suspension, secret rotation, token revocation, and user-grant revocation is written to the Identity portal audit log.</p><p>Remote MCP tool calls are also logged in Astro admin audit with the tool name and result status. Tool logs must not include API keys, OTPs, webhook secrets, raw national IDs, or full account numbers.</p>',36)])])}const k=t(d,[["render",r]]);export{u as __pageData,k as default};
